sys_declarative_action_assignment.client_script:
function onClick() {

    if (g_scratchpad.showWorkedTime == "true" && g_scratchpad.timeWorkedTables == true) {


        setModalCommon(g_scratchpad.modalTitle);


    } else {
        g_form.setValue("state", "3");
        g_form.save();

    }


}

function setModalCommon(modalTitle) {
    var formDataStr = replaceSpecChars(g_form);

    var tableName = g_form.getTableName();
    var formAction = "sow_close_change_request";

    var recId = g_form.getUniqueValue();
    var ga = new GlideAjax("global.HoCITSMCommonAjaxUtils");
    ga.addParam("sysparm_name", "getFieldsForModal");
    ga.addParam("sysparm_tablename", tableName);
    ga.addParam("sysparm_recid", recId);
    ga.addParam("sysparm_actionname", formAction);
    ga.addParam("sysparm_other", formDataStr);

    ga.getXMLAnswer(function(response) {

        var fields = JSON.parse(response);


        g_modal.showFields({
            title: modalTitle,
            fields: fields,
            size: 'lg'
        }).then(function(fieldValues) {
            processInput(fieldValues, g_form, formAction);
        }); //thenfunction 

    });


}


function processInput(fieldValues, g_form, formAction) {

    var stValidForZero = g_scratchpad.validForZero;
    var vMinsValue = fieldValues.updatedFields[2].value;
    var totalTime = Number(fieldValues.updatedFields[0].value) + Number(fieldValues.updatedFields[2].value);

    if (vMinsValue < 1 || isNaN(vMinsValue) === true) {
        alert(stValidForZero);
        return false;
    } else {
        var vHoursNew = Math.floor(totalTime < 60 ? 0 : totalTime / 60);
        var vMinsNew = Math.floor(totalTime - Math.floor(vHoursNew) * 60);
        var vSecNew = 0;
        var newTimeWorked = vHoursNew.toString() + ":" + vMinsNew.toString() + ":" + vSecNew.toString();

        g_form.setValue('time_worked', newTimeWorked);



        sendToServer(fieldValues.updatedFields);
    }

}


function sendToServer(arrValues) {
    var closeCode = arrValues[3].value;
    var closeNotes = arrValues[4].value;

    g_form.setValue("close_code", closeCode);
    g_form.setValue("close_notes", closeNotes);
    g_form.setValue("state", "3");

    setTimeout(g_form.save(), 100);



}
function replaceSpecChars(g_form) {
    var formData = g_form.serialize();
    var newFormData = [];
	newFormData.push( {"name":"time_worked_start","value":g_scratchpad.time_worked_start});
    var flags = 'g';
    var regexpr = new RegExp(g_scratchpad.regExp, flags); // /\u201D|\u201C|\u0022|\u201E|\u201F{|}/g;

    for (var i = 0; i < formData.length; i++) {
        var formDataItem = {};

        formDataItem.name = formData[i].name.toString();
        if (formData[i].value) {
            formDataItem.value = formData[i].value.toString().replace("{", "(").replace("}", ")").replace(regexpr, '');
        } else
            formDataItem.value = '';

        newFormData.push(formDataItem);

    }
    var formDataStr = JSON.stringify(newFormData);
    return formDataStr;

}
